from pathlib import Path
import hashlib,json

ROOT=Path(__file__).resolve().parents[3]
BASE=ROOT/'data/additional/rfsd'
raw=BASE/'raw'
revision=json.loads((raw/'dataset_info.json').read_text())['sha']
profile=json.loads((BASE/'derived/profile.json').read_text())
source={'source_inventory.json':'https://huggingface.co/api/datasets/irlspbru/RFSD/tree/main?recursive=true&expand=false','dataset_info.json':'https://huggingface.co/api/datasets/irlspbru/RFSD','dataset_card.md':f'https://huggingface.co/datasets/irlspbru/RFSD/raw/{revision}/README.md','upstream_README.md':'https://raw.githubusercontent.com/irlcode/RFSD/main/README.md','LICENCE':'https://raw.githubusercontent.com/irlcode/RFSD/main/LICENCE','descriptive_names_dict.csv':'https://raw.githubusercontent.com/irlcode/RFSD/main/aux_data/descriptive_names_dict.csv'}
for name in ['1b_build_rosstat_panel.R','2c_parse_fns_xmls.R','2d_build_fns_panel.R']:
    source[name]='https://raw.githubusercontent.com/irlcode/RFSD/main/code/1_prepare_financials/'+name
source['parsing_functions.R']='https://raw.githubusercontent.com/irlcode/RFSD/main/code/1_prepare_financials/helpers/parsing_functions.R'
source.update({'zenodo_record_14622209.json':'https://zenodo.org/api/records/14622209','zenodo_latest_record.json':'https://zenodo.org/api/records/14622209/versions/latest','zenodo_archive_inventory.json':'https://zenodo.org/api/records/22257046/files/RFSD.zip/content','zenodo_zip_tail_131072.bin':'https://zenodo.org/api/records/22257046/files/RFSD.zip/content','zenodo_zip_tail_headers.txt':'https://zenodo.org/api/records/22257046/files/RFSD.zip/content'})
verified={r['source_path']:r for r in profile['annual_profiles']}
backlog=json.loads((BASE/'derived/historical_backlog.json').read_text())
backlog_by_path={r['path']:r for r in backlog}
files=[]
for p in sorted(BASE.rglob('*')):
    if not p.is_file():continue
    rel=str(p.relative_to(BASE));rawrel=str(p.relative_to(raw)) if p.is_relative_to(raw) else None
    annual=verified.get(rawrel)
    incomplete=backlog_by_path.get(str(p.relative_to(ROOT)))
    source_path=rawrel.removeprefix('backlog/').removesuffix('.partial') if incomplete else rawrel
    entry={'path':str(p.relative_to(ROOT)),'source_url':f'https://huggingface.co/datasets/irlspbru/RFSD/resolve/{revision}/{source_path}' if annual or incomplete else source.get(rawrel),'retrieved_date_utc':'2026-11-07','bytes':p.stat().st_size,'allocated_bytes':p.stat().st_blocks*512,'sha256':annual['sha256'] if annual else hashlib.file_digest(p.open('rb'),'sha256').hexdigest(),'rows':annual['rows'] if annual else None,'year':annual['year'] if annual else (incomplete['year'] if incomplete else None),'kind':'published_data' if annual else ('incomplete_optional_backlog' if incomplete else ('source_documentation' if rawrel else 'derived_profile'))}
    if incomplete:entry.update(validated_range_bytes=incomplete['validated_range_bytes'],expected_complete_bytes=incomplete['full_published_bytes'],warning='Incomplete sparse file; SHA256 describes current retained bytes including holes, not publisher file. Do not load as usable Parquet.')
    files.append(entry)
manifest={'dataset':'Russian Financial Statements Database (RFSD)','release':'3.1.0','pinned_hf_revision':revision,'source_paper':'https://arxiv.org/abs/2501.05841','author_repository':'https://github.com/irlcode/RFSD','source_dataset':'https://huggingface.co/datasets/irlspbru/RFSD','retrieved_date_utc':'2026-11-07','coverage':'Complete current2025 and historical2011 slices; optional historical backlog is incomplete','raw_parquet_bytes':profile['raw_parquet_bytes'],'rows':profile['rows'],'period':profile['period'],'license':'CC-BY-4.0','license_url':'https://creativecommons.org/licenses/by/4.0/','financial_units':'Thousands of RUB; no local rescaling','files':files,'software':'Python 3.12; PyArrow 26.0.1; curl','acquisition_notes':['Default sandbox shell DNS unavailable; network-enabled curl succeeded.','Python urllib TLS issuer validation failed locally; system curl verified TLS successfully; no insecure bypass.','Initial single-stream transfers were resumed at contiguous byte offsets using verified public Content-Range requests; final whole-file SHA256 matches publisher LFS hash for every annual file.','Raw file sizes alone must not be used to judge resumed sparse download completeness; final hashes and profile validate actual complete coverage.'],'limitations':['Underlying source is author harmonization and imputation rather than original filings. Preserve filed/imputed/outlier and geocoding-quality flags.','Geography represents incorporation addresses, not plants or establishments.','Financial form definitions change in 2025; lines 1230/1240 are not harmonized across that transition by the authors.','Some nonfinancial organizations and nonfilers are included, while many ineligible nonfilers and financial organizations are excluded.']}
manifest.update(coverage='Complete current 2025 slice and complete 2011 slice without coordinates; incomplete optional backlog for 2012–2024',complete_published_panel=False,complete_years=sorted(r['year'] for r in profile['annual_profiles']),geographically_usable_complete_years=[r['year'] for r in profile['annual_profiles'] if r['all_field_nonmissing_rows'].get('lat',0) and r['all_field_nonmissing_rows'].get('lon',0)],source_published_period=[2011,2025],source_published_parquet_bytes=7698421535,historical_backlog_years=[r['year'] for r in backlog],historical_backlog_validated_range_bytes=sum(r['validated_range_bytes'] for r in backlog),mirror={'url':'https://zenodo.org/records/22257046','version':'3.1.0','zip_bytes':4959752069,'publisher_zip_checksum':'md5:7aeebde64ad82cbdea15780dee280bf9','zip_not_downloaded_in_full':True,'retrieved_tail_range':'bytes 4959620997-4959752068','member_2025_uncompressed_bytes':533691331,'member_2025_crc32':'c5db2c50'},acquisition_failures=['HF dataset-viewer current-year filter returned HTTP500; actual released Parquet downloaded instead.','HTTP2 range responses sometimes failed with curl92 CANCEL; switched to HTTP1.1 and resumable1MiB ranges.','Historical download frozen by scope decision after preserving verified checkpoints and all retained partial files.'])
manifest['acquisition_notes'][2]='Complete usable annual files match pinned publisher SHA256. Optional incomplete years are explicitly separated and excluded from usable Parquet coverage.'
(ROOT/'datasets/additional/rfsd/manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
print(manifest['rows'],manifest['raw_parquet_bytes'],len(files))
